package com.oms.order.service;
import com.ruoyi.common.core.domain.R;
import com.oms.common.api.OrderStockClient;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

class OrderShipmentDispatchServiceTest {
    OrderShipmentServiceTest fixture;OrderShipmentDispatchService dispatch;OrderShipmentWmsClient wms;OrderWarehouseClient inventory;long shipment;
    @BeforeAll static void setup(){OrderShipmentServiceTest.setup();}
    Map<String,Object> row(Object...pairs){return fixture.row(pairs);}
    @BeforeEach void seed(){
        fixture=new OrderShipmentServiceTest();fixture.seed();wms=mock(OrderShipmentWmsClient.class);inventory=mock(OrderWarehouseClient.class);dispatch=new OrderShipmentDispatchService();ReflectionTestUtils.setField(dispatch,"repository",fixture.repository);ReflectionTestUtils.setField(dispatch,"wms",wms);ReflectionTestUtils.setField(dispatch,"inventory",inventory);
        fixture.db.update("UPDATE oms_platform_order SET platform_created='2026-10-10 10:00:00',processing_payload=?",encode(row("trade_fullinfo_get_response",row("trade",row("receiver_state","北京市","receiver_city","北京市","receiver_district","海淀区","receiver_address","测试地址")))));fixture.db.update("UPDATE oms_order SET review_at=NOW()");
        when(wms.resolve(anyString(),anyMap(),anyString())).thenReturn(R.ok(route()));when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("ACCEPTED")));when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("ACCEPTED")));
    }
    @AfterEach void clear(){fixture.db.update("DELETE FROM oms_order_shipment_dispatch");}
    Map<String,Object> route(){return row("connection_id",7,"connection_name","fixture","provider","QIMEN","api_version","2.0","environment","TEST","external_warehouse","EXT-W","external_owner","EXT-O");}
    long create(long qty){Map<String,Object> receipt=fixture.receipt(1,qty,"V1","R1");receipt.put("batch_code","B001");fixture.mirror(Arrays.asList(receipt));shipment=number(fixture.generate(0).get(0),"id");fixture.db.update("UPDATE oms_order_shipment SET status='WAIT_DISPATCH',carrier_code='SF',carrier_name='express',warehouse_carrier_code='SF',carrier_match_status='MATCHED',receiver_province='北京'");when(inventory.receipts(anyString(),anyLong(),anyString(),anyString())).thenReturn(R.ok(Arrays.asList(receipt)));return shipment;}
    Map<String,Object> document(){return fixture.db.query("SELECT * FROM oms_order_shipment WHERE id=?",ROW,shipment).get(0);}
    Map<String,Object> intent(){return fixture.db.query("SELECT * FROM oms_order_shipment_dispatch WHERE shipment_id=?",ROW,shipment).get(0);}
    Map<String,Object> reply(String state){Map<String,Object> task=intent();return row("id",77,"shipment_id",shipment,"shipment_sn",task.get("shipment_sn"),"payload_hash",task.get("payload_hash"),"dispatch_state",state,"external_order","ACCEPTED".equals(state)?"WMS-77":"","warehouse_status","ACCEPTED".equals(state)?"ACCEPT":"","last_error","FAILED".equals(state)?"warehouse rejected":"","query_message","");}
    Map<String,Object> request(long version){return row("items",Arrays.asList(row("id",shipment,"control_version",version)));}
    Map<String,Object> submit(long version){return dispatch.submit("VERIFY",request(version),"operator").get(0);}
    void due(){fixture.db.update("UPDATE oms_order_shipment_dispatch SET next_attempt=NOW(),lease_until=NULL");}
    long count(){return fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_dispatch",Long.class);}
    @Test void queuedIntentFreezesCarrierAndAcceptanceChangesOnlyRoutingProgress(){create(10);Map<String,Object> quantities=fixture.db.query("SELECT quantity,reserved_quantity FROM oms_order_line",ROW).get(0);assertEquals(true,submit(1).get("success"));assertEquals("DISPATCHING",document().get("status"));assertEquals("PENDING",intent().get("state"));assertEquals(false,fixture.service.detail("VERIFY",shipment).get("can_match_carrier"));assertEquals(false,fixture.summary().get("can_void"));assertEquals("DISPATCHING",fixture.summary().get("business_status"));dispatch.process("VERIFY",shipment);assertEquals("ACCEPTED",intent().get("state"));assertEquals("WAREHOUSE_PROCESSING",document().get("status"));assertEquals("WAREHOUSE_PROCESSING",fixture.summary().get("business_status"));assertEquals(10,number(fixture.summary(),"warehouse_accepted_quantity"));assertEquals(quantities,fixture.db.query("SELECT quantity,reserved_quantity FROM oms_order_line",ROW).get(0));assertEquals(0,number(fixture.summary(),"shipped_quantity"));assertFalse(fixture.service.detail("VERIFY",shipment).containsKey("payload_json"));assertEquals(false,submit(number(document(),"control_version")).get("success"));verify(wms,times(1)).submit(anyString(),anyMap(),anyString());}
    @Test void lostReplyIsQueriedAndNeverBlindlySubmittedAgain(){create(6);assertEquals(true,submit(1).get("success"));when(wms.submit(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException("timeout"));dispatch.process("VERIFY",shipment);assertEquals("UNKNOWN",intent().get("state"));assertEquals("DISPATCHING",document().get("status"));assertEquals(false,submit(2).get("success"));due();dispatch.process("VERIFY",shipment);assertEquals("ACCEPTED",intent().get("state"));verify(wms,times(1)).submit(anyString(),anyMap(),anyString());verify(wms,times(1)).query(anyString(),anyMap(),anyString());}
    @Test void definitiveFailureCanRetryTheSameSnapshotWithNewVersion(){create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("FAILED")));dispatch.process("VERIFY",shipment);String json=text(intent(),"payload_json");assertEquals("FAILED",intent().get("state"));assertEquals("WAIT_DISPATCH",document().get("status"));assertEquals(false,fixture.service.detail("VERIFY",shipment).get("can_match_carrier"));assertEquals(true,fixture.service.detail("VERIFY",shipment).get("can_dispatch"));assertEquals(true,submit(3).get("success"));when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->{assertEquals(true,((Map<?,?>)i.getArgument(1)).get("retry"));return R.ok(reply("ACCEPTED"));});dispatch.process("VERIFY",shipment);assertEquals(json,intent().get("payload_json"));assertEquals(1,count());verify(wms,times(2)).submit(anyString(),anyMap(),anyString());}
    @Test void sourceAndWarehouseConfigurationGuardsNeverCreateIntent(){create(6);fixture.db.update("UPDATE oms_order SET manual_hold=1");assertEquals(false,submit(1).get("success"));fixture.db.update("UPDATE oms_order SET manual_hold=0");fixture.db.update("UPDATE oms_platform_order SET change_pending=1");assertEquals(false,submit(1).get("success"));fixture.db.update("UPDATE oms_platform_order SET change_pending=0");when(wms.resolve(anyString(),anyMap(),anyString())).thenReturn(R.fail("虚仓为自动虚拟出库"));assertTrue(text(dispatch.preview("VERIFY",request(1)).get(0),"message").contains("自动虚拟"));assertEquals(false,submit(1).get("success"));assertEquals(0,count());verify(wms,never()).submit(anyString(),anyMap(),anyString());}
    @Test void queuedHoldStopsCreateUntilReleased(){create(6);submit(1);fixture.db.update("UPDATE oms_order SET manual_hold=1");dispatch.process("VERIFY",shipment);assertEquals("PENDING",intent().get("state"));assertTrue(text(intent(),"last_error").contains("挂起"));verify(wms,never()).submit(anyString(),anyMap(),anyString());fixture.db.update("UPDATE oms_order SET manual_hold=0");due();dispatch.process("VERIFY",shipment);assertEquals("ACCEPTED",intent().get("state"));}
    @Test void wrongReceiptAndTenantCannotSubmit(){create(6);Map<String,Object> wrong=fixture.receipt(1,5,"V1","R1");wrong.put("batch_code","B001");when(inventory.receipts(anyString(),anyLong(),anyString(),anyString())).thenReturn(R.ok(Arrays.asList(wrong)));assertEquals(false,submit(1).get("success"));assertEquals(false,dispatch.submit("OTHER",request(1),"test").get(0).get("success"));assertEquals(0,count());verify(wms,never()).resolve(anyString(),anyMap(),anyString());}
    @Test void concurrentSubmissionHasOneIntentAndOneWinner() throws Exception {create(6);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Boolean>> jobs=new ArrayList<>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{start.await();return Boolean.TRUE.equals(submit(1).get("success"));}));start.countDown();int winners=0;for(Future<Boolean> job:jobs)if(job.get(10,TimeUnit.SECONDS))winners++;assertEquals(1,winners);}finally{pool.shutdownNow();}assertEquals(1,count());assertEquals(2,number(document(),"control_version"));}
    @Test void unknownNotFoundDoesNotReleaseStockAndAcceptedQueryDoesNotPostShipmentQuantity(){create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException());dispatch.process("VERIFY",shipment);when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply("UNKNOWN");reply.put("query_message","仓库查无单据，请核对");return R.ok(reply);});dispatch.query("VERIFY",shipment,"operator");assertEquals("UNKNOWN",intent().get("state"));assertEquals(false,submit(2).get("success"));assertEquals(10,fixture.db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply("ACCEPTED");reply.put("warehouse_status","DELIVERED");reply.put("query_message","等待完整出库明细回传");return R.ok(reply);});dispatch.query("VERIFY",shipment,"operator");assertEquals(0,number(fixture.summary(),"shipped_quantity"));assertEquals("WAREHOUSE_PROCESSING",document().get("status"));}
    @Test void queuedVoidIsBlockedAndDefinitiveUnacceptedFailureCanStopLocally(){create(6);submit(1);OrderVoidService voids=fixture.voids(mock(OrderStockClient.class));Map<String,Object> body=row("orders",Arrays.asList(row("id",fixture.id,"control_version",2)),"reason","cancel","confirm_local_void",1);assertEquals(false,voids.request("VERIFY",body,"operator").get(0).get("submitted"));when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("FAILED")));dispatch.process("VERIFY",shipment);body.put("orders",Arrays.asList(row("id",fixture.id,"control_version",3)));assertEquals(true,voids.request("VERIFY",body,"operator").get(0).get("submitted"));assertEquals("CANCELED",intent().get("state"));assertEquals("VOIDING",document().get("status"));}
    @Test void mismatchedWarehouseAcknowledgementCannotMarkAccepted(){create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply("ACCEPTED");reply.put("payload_hash","different");return R.ok(reply);});dispatch.process("VERIFY",shipment);assertEquals("UNKNOWN",intent().get("state"));assertEquals("DISPATCHING",document().get("status"));assertEquals(false,fixture.summary().get("can_void"));}
    @Test void missingBridgeLedgerCannotRequeueAnUnknownWarehouseOutcome(){create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException("lost reply"));dispatch.process("VERIFY",shipment);when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(row("dispatch_state","MISSING")));Map<String,Object> reply=dispatch.query("VERIFY",shipment,"operator");assertEquals("UNKNOWN",reply.get("dispatch_state"));assertTrue(text(reply,"message").contains("不能自动重新下发"));due();dispatch.process("VERIFY",shipment);verify(wms,times(1)).submit(anyString(),anyMap(),anyString());assertEquals("UNKNOWN",intent().get("state"));}
}
